```html
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Folding Stool - 3D</title>
<style>
  body { margin: 0; overflow: hidden; background: #1a1a1a; font-family: sans-serif; }
  #info { position: absolute; top: 10px; left: 10px; color: #ccc; font-size: 13px; }
</style>
</head>
<body>
<div id="info">Folding stool — drag to rotate, scroll to zoom</div>
<script type="importmap">
{
  "imports": {
    "three": "https://unpkg.com/three@0.160.0/build/three.module.js",
    "three/addons/": "https://unpkg.com/three@0.160.0/examples/jsm/"
  }
}
</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';

// dimensions in cm
const LEG_LENGTH = 45;
const HALF_SPREAD = 15; // w: ground contact points at x = ±w
// legs cross at their midpoint; H solves (2w)^2 + H^2 = LEG_LENGTH^2
const SEAT_HEIGHT = Math.sqrt(LEG_LENGTH ** 2 - (2 * HALF_SPREAD) ** 2);
const STOOL_WIDTH = 30; // depth/width, perpendicular to the original side-view sketch
const LEG_RADIUS = 1.1;
const BOLT_RADIUS = 1.6;
const SAG = 2.5;

const w = HALF_SPREAD, H = SEAT_HEIGHT;
const zFront = -STOOL_WIDTH / 2, zBack = STOOL_WIDTH / 2;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a1a);

const camera = new THREE.PerspectiveCamera(45, innerWidth / innerHeight, 0.1, 1000);
camera.position.set(80, 60, 100);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
document.body.appendChild(renderer.domElement);

const controls = new OrbitControls(camera, renderer.domElement);
controls.target.set(0, H / 2, 0);
controls.enableDamping = true;

scene.add(new THREE.AmbientLight(0xffffff, 0.5));
const dl = new THREE.DirectionalLight(0xffffff, 0.8);
dl.position.set(50, 80, 50);
dl.castShadow = true;
scene.add(dl);

const floor = new THREE.Mesh(
  new THREE.PlaneGeometry(200, 200),
  new THREE.MeshStandardMaterial({ color: 0x2a2a2a })
);
floor.rotation.x = -Math.PI / 2;
floor.receiveShadow = true;
scene.add(floor);

const woodMat = new THREE.MeshStandardMaterial({ color: 0x8a5a34, roughness: 0.6 });
const metalMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, metalness: 0.8, roughness: 0.3 });
const canvasMat = new THREE.MeshStandardMaterial({ color: 0xcdb891, roughness: 0.9, side: THREE.DoubleSide });

// generic cylinder-between-two-points helper, reused for legs and the bolt
function makeCylinderBetween(a, b, radius, material) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const length = dir.length();
  const geo = new THREE.CylinderGeometry(radius, radius, length, 16);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  // align cylinder's default Y-axis with the direction vector
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  mesh.castShadow = true;
  return mesh;
}

// two X-leg assemblies, front and back
for (const z of [zFront, zBack]) {
  scene.add(makeCylinderBetween(
    new THREE.Vector3(-w, 0, z), new THREE.Vector3(w, H, z), LEG_RADIUS, woodMat
  ));
  scene.add(makeCylinderBetween(
    new THREE.Vector3(w, 0, z), new THREE.Vector3(-w, H, z), LEG_RADIUS, woodMat
  ));
}

// bolt/axle through both crossing points
const midY = H / 2;
const boltA = new THREE.Vector3(0, midY, zFront - 3);
const boltB = new THREE.Vector3(0, midY, zBack + 3);
scene.add(makeCylinderBetween(boltA, boltB, BOLT_RADIUS, metalMat));

[boltA, boltB].forEach(p => {
  const nut = new THREE.Mesh(
    new THREE.CylinderGeometry(BOLT_RADIUS * 1.6, BOLT_RADIUS * 1.6, 1.2, 6),
    metalMat
  );
  nut.position.copy(p);
  nut.rotation.x = Math.PI / 2;
  nut.castShadow = true;
  scene.add(nut);
});

// sagging canvas seat strap between the two top ends, spanning the full stool width
function buildSeat() {
  const lengthSegs = 24, widthSegs = 3;
  const positions = [], indices = [], uvs = [];
  for (let i = 0; i <= lengthSegs; i++) {
    const u = i / lengthSegs;
    const x = -w + u * (2 * w);
    const y = H - SAG * Math.sin(Math.PI * u);
    for (let j = 0; j <= widthSegs; j++) {
      const v = j / widthSegs;
      const z = zFront + v * (zBack - zFront);
      positions.push(x, y, z);
      uvs.push(u, v);
    }
  }
  for (let i = 0; i < lengthSegs; i++) {
    for (let j = 0; j < widthSegs; j++) {
      const a = i * (widthSegs + 1) + j;
      const b = a + 1;
      const c = a + (widthSegs + 1);
      const d = c + 1;
      indices.push(a, c, b, b, c, d);
    }
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
  geo.setIndex(indices);
  geo.computeVertexNormals();
  const mesh = new THREE.Mesh(geo, canvasMat);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  return mesh;
}
scene.add(buildSeat());

function animate() {
  requestAnimationFrame(animate);
  controls.update();
  renderer.render(scene, camera);
}
animate();

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});
</script>
</body>
</html>
```

What it does: extrudes your side-view sketch into two mirrored X-leg assemblies (front/back, 30 cm apart), joined by a metal bolt/axle running through both crossing points, with a canvas seat strip that sags realistically between the two top leg ends. Legs are 45 cm with a 30 cm ground spread, giving a ~33.5 cm seat height. Drag to orbit, scroll to zoom.

